import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { dirname, join } from "pathe";

type GenerationMode = "sync" | "scaffold";

export interface GeneratedFile {
  readonly path: string;
  readonly content: string;
}

export interface EmitFilesResult {
  readonly outDir: string;
  readonly written: readonly string[];
  readonly skipped: readonly string[];
  readonly deleted: readonly string[];
  readonly unchanged: readonly string[];
  readonly drifted: readonly string[];
}

const GENERATED_SYNC_HEADER =
  "// Generated by @defjs/cli. Do not edit directly.";
const GENERATED_SCAFFOLD_HEADER = "// Scaffolded by @defjs/cli.";

const GENERATED_TOOL_IGNORE_LINES = [
  "/* eslint-disable */",
  "/* oxlint-disable */",
  "// biome-ignore-all lint: generated file",
  "// biome-ignore-all format: generated file",
  "// biome-ignore-all assist: generated file",
  "// deno-lint-ignore-file",
  "// deno-fmt-ignore-file",
  "// dprint-ignore-file",
] as const;

export function headerForMode(mode: GenerationMode): string {
  return mode === "scaffold"
    ? [GENERATED_SCAFFOLD_HEADER, ...GENERATED_TOOL_IGNORE_LINES].join("\n")
    : [
        GENERATED_SYNC_HEADER,
        "// @generated",
        ...GENERATED_TOOL_IGNORE_LINES,
      ].join("\n");
}

function listFilesRecursive(dir: string): string[] {
  if (!existsSync(dir)) {
    return [];
  }
  const files: string[] = [];
  const walk = (currentDir: string, prefix: string): void => {
    for (const entry of readdirSync(currentDir, { withFileTypes: true })) {
      const relPath = prefix === "" ? entry.name : `${prefix}/${entry.name}`;
      if (entry.isDirectory()) {
        walk(join(currentDir, entry.name), relPath);
      } else if (entry.isFile()) {
        files.push(relPath);
      }
    }
  };
  walk(dir, "");
  return files.sort();
}

function isManagedFile(content: string): boolean {
  return content.startsWith(GENERATED_SYNC_HEADER);
}

export function applyGeneratedFiles(
  outDir: string,
  planned: readonly GeneratedFile[],
  options: {
    readonly mode: GenerationMode;
    readonly check: boolean;
  },
): EmitFilesResult {
  const plannedByPath = new Map<string, string>();
  for (const file of planned) {
    plannedByPath.set(file.path, file.content);
  }

  const written: string[] = [];
  const skipped: string[] = [];
  const deleted: string[] = [];
  const unchanged: string[] = [];
  const drifted: string[] = [];

  for (const file of planned) {
    const absPath = join(outDir, file.path);
    const exists = existsSync(absPath);
    if (!exists) {
      if (options.check) {
        drifted.push(file.path);
      } else {
        mkdirSync(dirname(absPath), { recursive: true });
        writeFileSync(absPath, file.content, "utf8");
        written.push(file.path);
      }
      continue;
    }

    const current = readFileSync(absPath, "utf8");
    if (options.mode === "scaffold") {
      if (options.check) {
        unchanged.push(file.path);
      } else {
        skipped.push(file.path);
      }
      continue;
    }

    if (current === file.content) {
      unchanged.push(file.path);
    } else if (options.check) {
      drifted.push(file.path);
    } else {
      mkdirSync(dirname(absPath), { recursive: true });
      writeFileSync(absPath, file.content, "utf8");
      written.push(file.path);
    }
  }

  if (options.mode === "sync") {
    const existingFiles = listFilesRecursive(outDir);
    for (const relPath of existingFiles) {
      if (plannedByPath.has(relPath)) {
        continue;
      }
      const absPath = join(outDir, relPath);
      const current = readFileSync(absPath, "utf8");
      if (!isManagedFile(current)) {
        continue;
      }
      if (options.check) {
        drifted.push(relPath);
      } else {
        rmSync(absPath, { force: true });
        deleted.push(relPath);
      }
    }
  }

  return {
    outDir,
    written: written.sort(),
    skipped: skipped.sort(),
    deleted: deleted.sort(),
    unchanged: unchanged.sort(),
    drifted: drifted.sort(),
  };
}
